#!/usr/bin/env python3
from pathlib import Path
import base64, lzma, os, sys, traceback

_manifest_path = Path(".msc-build/approved-theme-finish-v2-manifest.json")
try:
    _source_bytes = lzma.decompress(base64.b64decode(""))
    try:
        exec(compile(_source_bytes, __file__, "exec"))
    except SystemExit:
        if not _manifest_path.is_file():
            raise
    if not _manifest_path.is_file():
        raise RuntimeError("Theme finish manifest was not created.")
    sys.stdout.flush()
    sys.stderr.flush()
    os._exit(0)
except BaseException:
    traceback.print_exc()
    sys.stdout.flush()
    sys.stderr.flush()
    os._exit(1)
